    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0x832AF9F8BA7C94A7ULL + 0xE849B1E357394CC8ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0xBFD43D03A77CC5DDULL + 0xB23B388C10949E4DULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseC(pNonce * 0x8B01D31E9882F33DULL + 0x97D5DA1970D296E0ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0xAF07C30199CA2EA1ULL + 0xB472E48DB87CFCDAULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseA(pNonce * 0x8DBF5880FF37592FULL + 0xB07F001809AB6D21ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseB(pNonce * 0x910702448AE9C389ULL + 0xEE0ADB01BEA51CEAULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseA(pNonce * 0xEB706AF2AF025551ULL + 0xE62645E19AC40793ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordH = TwistMix64::DiffuseC(pNonce * 0xFA143A08C0E7CD37ULL + 0xCF36ED460123B32FULL);
    [[maybe_unused]] const std::uint64_t aNonceWordI = TwistMix64::DiffuseC(pNonce * 0xEDEF6D75A3718A1BULL + 0x8DC21A01F67D1482ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordJ = TwistMix64::DiffuseC(pNonce * 0xF6C0F88DAE7EB93DULL + 0x9EA2127FBD4F5A42ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordK = TwistMix64::DiffuseC(pNonce * 0xD56705B8C7C422ADULL + 0xE3114E2149393886ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseB(pNonce * 0xB0ED41C166312B1FULL + 0xC20BEE3A1F5EC41EULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseA(pNonce * 0xC87A87B34AC6D073ULL + 0xB5B7DE307B03706DULL);
    [[maybe_unused]] const std::uint64_t aNonceWordN = TwistMix64::DiffuseA(pNonce * 0xE74786B18730454BULL + 0x9DBF840D5559E1E0ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordO = TwistMix64::DiffuseA(pNonce * 0xF0A3184D36F227A3ULL + 0xB656BD93F63278AFULL);
