        //      aFuseLaneC (-->), aFuseLaneA (-->), aFireLaneC (<-?->)
        //
        // Cross:
        //      aFuseLaneB (<--), aWaterLaneD (<--), aFireLaneD (<-?->)
        //
        // Destination:
        //      aFuseLaneD
