            //
            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 29953U)) & S_BLOCK1], 37U) ^ RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 29940U)) & S_BLOCK1], 57U));
            aCross ^= RotL64(aFireLaneD[((aIndex + 31444U)) & S_BLOCK1], 10U);
