            //
            aScatter = (RotL64(aPrevious, 39U) ^ RotL64(aCross, 51U)) + (RotL64(aCarry, 21U) ^ RotL64(aIngress, 4U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterH = (aWandererH + RotL64(aCross, 46U)) + 0x1FB2E2E78C0D8C94ULL;
            aOrbiterF = (aWandererB + RotL64(aPrevious, 35U)) + 0x6D762317E4CEAB10ULL;
            aOrbiterK = (aWandererE + RotL64(aIngress, 29U)) + 0x192BBEE99AD2D3B3ULL;
            aOrbiterE = (aWandererG + RotL64(aScatter, 11U)) + 0x0B83B4AE538D5902ULL;
            aOrbiterB = ((aWandererK + RotL64(aCross, 21U)) + RotL64(aCarry, 3U)) + 0x03262DA9D698934AULL;
            aOrbiterG = (((aWandererD + RotL64(aScatter, 57U)) + RotL64(aCarry, 27U)) + 0x6D149A284F028F98ULL) + aTwistOrbiterAssignSaltA[(((255U - aIndex) + 26U)) & S_SALT1];
            aOrbiterC = (((aWandererC + RotL64(aPrevious, 5U)) + RotL64(aCarry, 41U)) + 0x0DAEAE0C07DF38E8ULL) + aTwistOrbiterAssignSaltF[(((255U - aIndex) + 193U)) & S_SALT1];
            //
            aOrbiterH = ((aOrbiterH + aOrbiterF) + 0x466B350FC3DFA784ULL) + aTwistOrbiterUpdateSaltB[(((255U - aIndex) + 29U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0x5B733FB6A0D4C58AULL;
