            aOrbiterK = (aOrbiterK + aOrbiterE) + 0xDDD7BEE03CADF4C0ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterK) ^ 0x86A393A88CBBC191ULL) ^ aTwistOrbiterUpdateSaltC[(((255U - aIndex) + 98U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x8C32FB2D66B47487ULL), 39U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0x26090EB7889EC8B2ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterE) ^ 0x9FDF0AE536B4B9F4ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 181U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x434AD337310983FBULL), 19U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x4DE1C96770E6377BULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterC) ^ 0x7CC1E736CA1E5CE5ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x20B72EE22F770DC7ULL), 53U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x5C9EEB1049A56699ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0x3A8274F5B6933D92ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x8FE3E56A711891D5ULL), 47U);
