            //
            aWandererE = aWandererE + ((((RotL64(aIngress, 21U) + aOrbiterC) + RotL64(aOrbiterH, 29U)) + RotL64(aCarry, 51U)) + aTwistWandererUpdateSaltA[((aIndex + 105U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aCross, 51U) + RotL64(aOrbiterF, 5U)) + aOrbiterC);
            aWandererC = aWandererC + ((RotL64(aScatter, 37U) + RotL64(aOrbiterF, 35U)) + aOrbiterH);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 30U) + aOrbiterK) + RotL64(aOrbiterB, 13U));
            aWandererB = aWandererB + ((RotL64(aIngress, 57U) + RotL64(aOrbiterE, 41U)) + aOrbiterF);
