            aOrbiterE = (((aWandererI + RotL64(aIngress, 51U)) + RotL64(aCarry, 47U)) + 0x3733BA832C30D768ULL) + aTwistOrbiterAssignSaltD[(((255U - aIndex) + 68U)) & S_SALT1];
