            //
            aIngress = (RotL64(aLightningLaneA[((aIndex + 6561U)) & S_BLOCK1], 56U) ^ RotL64(aHeartLaneC[((aIndex + 9075U)) & S_BLOCK1], 37U));
            aIngress ^= (RotL64(pCrossLaneC[((aIndex + 7821U)) & S_BLOCK1], 11U) ^ RotL64(aSource[((aIndex + 8507U)) & S_BLOCK1], 19U));
            aIngress = TwistMix64::DiffuseA((aIngress ^ aTwistDomainWordIngress));
