            aScatter = (RotL64(aPrevious, 41U) + RotL64(aCarry, 53U)) ^ (RotL64(aCross, 12U) ^ RotL64(aIngress, 27U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
