            //
            aOrbiterE = (aWandererI + RotL64(aCross, 43U)) + 0x992B53D1733E6E1AULL;
            aOrbiterC = (((aWandererE + RotL64(aIngress, 27U)) + RotL64(aCarry, 35U)) + 0xD59C2E649278F05FULL) + aTwistOrbiterAssignSaltE[(((255U - aIndex) + 171U)) & S_SALT1];
            aOrbiterF = ((aWandererD + RotL64(aPrevious, 37U)) + RotL64(aCarry, 43U)) + 0xC48A73DF45F64E18ULL;
