            aWandererE = aWandererE + ((RotL64(aPrevious, 47U) + RotL64(aOrbiterJ, 24U)) + aOrbiterB);
            aWandererH = aWandererH ^ ((RotL64(aIngress, 60U) + aOrbiterE) + RotL64(aOrbiterI, 5U));
